html:
{% set is_draft = doc.docstatus == 0 %}
{% set is_cancelled = doc.docstatus == 2 %}
{% set is_return = doc.is_return == 1 %}
{% set title = 'DEBIT NOTE' if is_return else 'TAX INVOICE' %}
{% set ns = namespace(pr_list=[], first_cc='', first_loc='') %}
{% for it in doc.items %}{% if it.purchase_receipt and it.purchase_receipt not in ns.pr_list %}{% set _ = ns.pr_list.append(it.purchase_receipt) %}{% endif %}{% if it.cost_center and not ns.first_cc %}{% set ns.first_cc = it.cost_center %}{% endif %}{% if it.ts_delivery_location and not ns.first_loc %}{% set ns.first_loc = it.ts_delivery_location %}{% endif %}{% endfor %}
{% set pr_count = ns.pr_list | length %}
{% set pr_display = (', '.join(ns.pr_list)) if pr_count > 0 else (doc.ts_purchase_receipt or '-') %}
{% set supp_addr = frappe.get_doc('Address', doc.supplier_address) if doc.supplier_address else None %}

<style>
@page { size: A4; margin: 6mm 8mm 6mm 8mm; }
body { font-family: Arial, sans-serif; font-size: 10px; color: #000; }
.bbpl-wrap { position: relative; }
.bbpl-title-block { text-align: center; margin: 6px 0 4px 0; }
.bbpl-draft-stamp { font-size: 13px; font-weight: bold; letter-spacing: 2px; margin-bottom: 2px; }
.bbpl-title { font-size: 16px; font-weight: bold; text-decoration: underline; letter-spacing: 1px; }
.bbpl-info-table { width: 100%; border-collapse: collapse; margin: 0 0 4px 0; }
.bbpl-info-table td { padding: 3px 6px; font-size: 11px; vertical-align: middle; border: 1px solid #000; }
.bbpl-info-label { font-weight: bold; width: 22%; background: #eee; text-align: center; }
.bbpl-info-value { width: 28%; text-align: center; }
.bbpl-section-heading { font-size: 12px; font-weight: bold; text-decoration: underline; margin: 8px 0 3px; }
.bbpl-context-table { width: 100%; border-collapse: collapse; margin: 0 0 4px 0; }
.bbpl-context-table td { padding: 3px 6px; font-size: 11px; vertical-align: middle; border: 1px solid #000; }
.bbpl-context-label { font-weight: bold; width: 22%; background: #f5f5e8; text-align: center; }
.bbpl-context-value { width: 28%; text-align: center; }
.bbpl-qc-override { margin: 6px 0; padding: 6px 10px; border: 1px solid #c08a00; border-left: 4px solid #c08a00; background: #fff4d6; font-size: 10px; color: #000; }
.bbpl-qc-override b { color: #8a4a00; }
.bbpl-items { width: 100%; border-collapse: collapse; margin: 4px 0 0 0; }
.bbpl-items th { background: #e8e8e8; border: 1px solid #000; padding: 4px 6px; font-size: 10px; text-align: center; font-weight: bold; }
.bbpl-items td { border: 1px solid #000; padding: 3px 6px; font-size: 11px; vertical-align: top; }
.bbpl-items .num { text-align: right; white-space: nowrap; }
.bbpl-items .ctr { text-align: center; }
.bbpl-items .item-spec { font-size: 10px; color: #111; margin-top: 3px; line-height: 1.4; }
.bbpl-items tfoot td { padding: 4px 6px; font-size: 11px; font-weight: bold; }
.bbpl-items tfoot .total-lbl { text-align: right; background: #eee; }
.bbpl-items tfoot .total-val { text-align: right; white-space: nowrap; }
.bbpl-items tfoot .grand .total-lbl, .bbpl-items tfoot .grand .total-val { background: #cce6ff; font-size: 12px; }
.bbpl-in-words { font-size: 11px; padding: 4px 6px; margin-top: 2px; border: 1px solid #000; background: #fafafa; font-style: italic; }
.bbpl-pay-table { width: 100%; border-collapse: collapse; margin: 4px 0 0 0; }
.bbpl-pay-table th { background: #e8e8e8; border: 1px solid #000; padding: 4px 6px; font-size: 10px; text-align: center; font-weight: bold; }
.bbpl-pay-table td { border: 1px solid #000; padding: 3px 6px; font-size: 11px; vertical-align: middle; }
.bbpl-pay-table .num { text-align: right; white-space: nowrap; }
.bbpl-static-note { margin: 6px 0; padding: 5px 8px; background: #fff7d6; border-left: 4px solid #c08a00; font-size: 10px; }
.bbpl-sign-table { width: 100%; border-collapse: collapse; margin: 12px 0 0 0; }
.bbpl-sign-table td { border: none !important; padding: 0 6px; vertical-align: top; width: 50%; }
.bbpl-sign-box { border-top: 1px solid #000; padding-top: 3px; text-align: center; font-size: 11px; font-weight: bold; }
.bbpl-sign-box .sub { display: block; font-weight: normal; font-size: 9px; color: #333; margin-top: 1px; }
.bbpl-sign-spacer { height: 22px; }
.bbpl-footer { margin-top: 8px; border-top: 1px solid #000; padding-top: 4px; text-align: center; font-size: 9px; color: #111; line-height: 1.3; page-break-inside: avoid; }
.bbpl-footer .fname { font-weight: bold; font-size: 10px; color: #000; }
.bbpl-sign-table, .bbpl-context-table, .bbpl-info-table, .bbpl-pay-table { page-break-inside: avoid; }
.bbpl-watermark { position: fixed; top: 35%; left: 8%; font-size: 110px; color: rgba(255,0,0,0.08); font-weight: bold; transform: rotate(-30deg); -webkit-transform: rotate(-30deg); z-index: 0; letter-spacing: 18px; pointer-events: none; }
</style>

<div class="bbpl-wrap">

{% if is_draft %}<div class="bbpl-watermark">DRAFT</div>{% endif %}
{% if is_cancelled %}<div class="bbpl-watermark" style="color: rgba(0,0,0,0.10);">CANCELLED</div>{% endif %}

<div style="text-align:center; margin:0 0 6px 0;"><img src="/files/BBPL-LH.png" alt="BBPL Letterhead" style="max-width:100%; height:auto; display:block; margin:0 auto;" onerror="this.style.display='none'"></div>

<div class="bbpl-title-block">
  {% if is_draft %}<div class="bbpl-draft-stamp" style="color:#cc0000;">DRAFT</div>{% endif %}
  {% if is_cancelled %}<div class="bbpl-draft-stamp" style="color:#000;">CANCELLED</div>{% endif %}
  <div class="bbpl-title">{{ title | e }}</div>
</div>

<table class="bbpl-info-table">
<tr>
  <td class="bbpl-info-label">Invoice No</td>
  <td class="bbpl-info-value"><b>{{ doc.name | e }}</b></td>
  <td class="bbpl-info-label">Posting Date</td>
  <td class="bbpl-info-value">{{ frappe.format(doc.posting_date, {'fieldtype': 'Date'}) }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Supplier</td>
  <td class="bbpl-info-value"><b>{{ (doc.supplier_name or doc.supplier or '') | e }}</b></td>
  <td class="bbpl-info-label">Supplier Invoice No / Date</td>
  <td class="bbpl-info-value"><b>{{ (doc.bill_no or '-') | e }}</b>{% if doc.bill_date %} <br><span style="font-size:10px;">{{ frappe.format(doc.bill_date, {'fieldtype': 'Date'}) }}</span>{% endif %}</td>
</tr>
{% if supp_addr %}
<tr>
  <td class="bbpl-info-label">Supplier Address</td>
  <td colspan="3" class="bbpl-info-value" style="text-align:left;">{{ (supp_addr.address_line1 or '') | e }}{% if supp_addr.address_line2 %}, {{ supp_addr.address_line2 | e }}{% endif %}{% if supp_addr.city %}, {{ supp_addr.city | e }}{% endif %}{% if supp_addr.state %}, {{ supp_addr.state | e }}{% endif %}{% if supp_addr.pincode %} - {{ supp_addr.pincode | e }}{% endif %}{% if supp_addr.country %}, {{ supp_addr.country | e }}{% endif %}</td>
</tr>
{% endif %}
<tr>
  <td class="bbpl-info-label">Due Date</td>
  <td class="bbpl-info-value">{% if doc.due_date %}{{ frappe.format(doc.due_date, {'fieldtype': 'Date'}) }}{% else %}-{% endif %}</td>
  <td class="bbpl-info-label">Status</td>
  <td class="bbpl-info-value">{{ (doc.status or '-') | e }}</td>
</tr>
<tr>
  <td class="bbpl-info-label">Cost Center</td>
  <td class="bbpl-info-value">{{ (doc.cost_center or ns.first_cc or '-') | e }}</td>
  <td class="bbpl-info-label">Project</td>
  <td class="bbpl-info-value">{{ (doc.project or '-') | e }}</td>
</tr>
{% if ns.first_loc %}
<tr>
  <td class="bbpl-info-label">Use Location</td>
  <td colspan="3" class="bbpl-info-value" style="text-align:left;">{{ ns.first_loc | e }}</td>
</tr>
{% endif %}
</table>

<div class="bbpl-section-heading">Receipt Context</div>
<table class="bbpl-context-table">
<tr>
  <td class="bbpl-context-label">Token No</td>
  <td class="bbpl-context-value"><b>{{ (doc.ts_token or '-') | e }}</b></td>
  <td class="bbpl-context-label">RST No</td>
  <td class="bbpl-context-value"><b>{{ (doc.ts_rst_number or '-') | e }}</b></td>
</tr>
<tr>
  <td class="bbpl-context-label">PO No</td>
  <td class="bbpl-context-value"><b>{{ (doc.ts_po_reference or '-') | e }}</b></td>
  <td class="bbpl-context-label">PR No{% if pr_count > 1 %} ({{ pr_count }}){% endif %}</td>
  <td class="bbpl-context-value"><b>{{ pr_display | e }}</b></td>
</tr>
{% if doc.ts_quality_inspection or doc.ts_deduction_sheet %}
<tr>
  <td class="bbpl-context-label">Quality Inspection</td>
  <td class="bbpl-context-value">{{ (doc.ts_quality_inspection or '-') | e }}</td>
  <td class="bbpl-context-label">Deduction Sheet</td>
  <td class="bbpl-context-value">{{ (doc.ts_deduction_sheet or '-') | e }}</td>
</tr>
{% endif %}
{% if doc.ts_qc_status %}
<tr>
  <td class="bbpl-context-label">QC Status</td>
  <td colspan="3" class="bbpl-context-value">{{ doc.ts_qc_status | e }}</td>
</tr>
{% endif %}
</table>

{% if doc.ts_qc_override %}
<div class="bbpl-qc-override">
  <b>&#9888; QUALITY OVERRIDE APPLIED</b><br>
  <b>Reason:</b> {{ (doc.ts_qc_override_reason or '-') | e }}<br>
  <b>Approved by:</b> {{ (doc.ts_qc_override_by or '-') | e }}{% if doc.ts_qc_override_at %} on {{ frappe.format(doc.ts_qc_override_at, {'fieldtype': 'Datetime'}) }}{% endif %}
</div>
{% endif %}

<table class="bbpl-items">
<thead>
<tr>
  <th style="width:30px">S.No</th>
  <th>Item</th>
  <th style="width:85px">Item Remark</th>
  <th style="width:55px">HSN</th>
  <th style="width:55px">Quantity</th>
  <th style="width:40px">Unit</th>
  <th style="width:70px">Rate</th>
  <th style="width:85px">GST</th>
  <th style="width:95px">Amount</th>
</tr>
</thead>
<tbody>
{% for item in doc.items %}
{% set tax_ns = namespace(amt=0, rate=0, label='') %}
{% if item.item_tax_template %}{% set _tpl = item.item_tax_template %}{% set _parts = _tpl.split('%') %}{% if _parts | length > 1 %}{% set _nums = _parts[0].replace('GST','').replace('-','').strip() %}{% if _nums %}{% set tax_ns.rate = _nums | float %}{% set tax_ns.amt = (item.amount or 0) * tax_ns.rate / 100 %}{% set tax_ns.label = 'GST' %}{% endif %}{% endif %}{% endif %}
{% if tax_ns.amt == 0 and (doc.taxes or []) %}{% set _t0 = doc.taxes[0] %}{% if _t0.rate and _t0.rate > 0 %}{% set tax_ns.rate = _t0.rate %}{% set tax_ns.amt = (item.amount or 0) * tax_ns.rate / 100 %}{% if 'IGST' in (_t0.account_head or '') %}{% set tax_ns.label = 'IGST' %}{% else %}{% set tax_ns.label = 'GST' %}{% endif %}{% endif %}{% endif %}
<tr>
  <td class="ctr">{{ loop.index }}</td>
  <td><b>{{ (item.item_name or item.item_code) | e }}</b>{% if item.description and item.description != (item.item_name or item.item_code) %}<div class="item-spec">{{ item.description | safe }}</div>{% endif %}</td>
  <td>{{ (item.ts_item_remark or '') | e }}</td>
  <td class="ctr">{{ (item.gst_hsn_code or '-') | e }}</td>
  <td class="num">{{ frappe.format(item.qty, {'fieldtype': 'Float', 'precision': 2}) }}</td>
  <td class="ctr">{{ (item.uom or item.stock_uom or '') | e }}</td>
  <td class="num">{{ frappe.format(item.rate, {'fieldtype': 'Currency'}) }}</td>
  <td class="num">{% if tax_ns.amt > 0 %}<b>{{ frappe.format(tax_ns.amt, {'fieldtype': 'Currency'}) }}</b><br><span style="font-size:9px;color:#444;">{{ (tax_ns.label or 'GST') | e }} {{ (tax_ns.rate | int) if tax_ns.rate == (tax_ns.rate | int) else tax_ns.rate }}%</span>{% else %}<span style="color:#666;font-size:10px;">Exempt</span>{% endif %}</td>
  <td class="num">{{ frappe.format(item.amount, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% endfor %}
</tbody>
<tfoot>
<tr>
  <td colspan="8" class="total-lbl">Net Total</td>
  <td class="total-val">{{ frappe.format(doc.net_total, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% for tax in doc.taxes %}
<tr>
  <td colspan="8" class="total-lbl">{{ (tax.description or tax.account_head or 'Tax') | e }}</td>
  <td class="total-val">{{ frappe.format(tax.tax_amount, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% endfor %}
<tr class="grand">
  <td colspan="8" class="total-lbl">Grand Total</td>
  <td class="total-val">{{ frappe.format(doc.grand_total, {'fieldtype': 'Currency'}) }}</td>
</tr>
</tfoot>
</table>

{% if doc.in_words %}
<div class="bbpl-in-words"><b>Amount in Words:</b> {{ doc.in_words | e }}</div>
{% endif %}

{% if doc.payment_schedule %}
<div class="bbpl-section-heading">Payment Terms</div>
<table class="bbpl-pay-table">
<thead>
<tr>
  <th style="width:90px">Due Date</th>
  <th>Description</th>
  <th style="width:60px">Invoice %</th>
  <th style="width:110px">Amount</th>
</tr>
</thead>
<tbody>
{% for ps in doc.payment_schedule %}
<tr>
  <td class="ctr">{% if ps.due_date %}{{ frappe.format(ps.due_date, {'fieldtype': 'Date'}) }}{% else %}-{% endif %}</td>
  <td>{{ (ps.description or (frappe.db.get_value('Payment Term', ps.payment_term, 'description') if ps.payment_term else '') or '') | e }}</td>
  <td class="num">{% if ps.invoice_portion %}{{ frappe.format(ps.invoice_portion, {'fieldtype': 'Percent', 'precision': 2}) }}{% else %}-{% endif %}</td>
  <td class="num">{{ frappe.format(ps.payment_amount, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% endfor %}
</tbody>
</table>
{% endif %}

<div class="bbpl-static-note">&#9888; Please mention this invoice number in your payment advice.</div>

{% if doc.terms %}
<div class="bbpl-section-heading">Terms and Conditions</div>
<div class="bbpl-in-words" style="font-style:normal;">{{ doc.terms | safe }}</div>
{% endif %}

<table class="bbpl-sign-table">
<tr>
  <td>
    <div class="bbpl-sign-spacer"></div>
    <div class="bbpl-sign-box">Prepared By (Accounts)<span class="sub">Name &amp; Signature / Date</span></div>
  </td>
  <td>
    <div class="bbpl-sign-spacer"></div>
    <div class="bbpl-sign-box">Authorised Signatory<span class="sub">Name &amp; Signature / Date</span></div>
  </td>
</tr>
</table>

<div class="bbpl-footer">
  <div class="fname">BETUL BIOFUEL PVT LTD</div>
  <div>Bodi Junawani, Betul (M.P.)</div>
  <div>GSTN:- 23AAJCB8781D1ZM</div>
  <div>Email:- betulbiofuelpvtld@gmail.com | Mobile no:- 7880138508</div>
</div>

</div>
